eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   getLegalCopy: () => (/* binding */ getLegalCopy)\n/* harmony export */ });\n/* harmony import */ var _config__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! ./config */ \"(rsc)/./src/locales/config.ts\");\n\nconst legalCopy = {\n    es: {\n        privacy: {\n            title: \"Pol\\xedtica de privacidad\",\n            intro: \"En Cojauny tratamos la informaci\\xf3n personal con responsabilidad y transparencia. Esta pol\\xedtica explica c\\xf3mo gestionamos los datos que nos facilitas cuando solicitas acceso a la beta, compartes feedback o navegas por la web.\",\n            updatedAt: \"Actualizado el 17 de noviembre de 2025\",\n            sections: [\n                {\n                    heading: \"Responsable del tratamiento\",\n                    body: 'Mientras formalizamos la sociedad mercantil definitiva, el tratamiento de datos recae en el equipo fundador de Cojauny (en adelante, \"Equipo Cojauny\"), con organizaci\\xf3n en Espa\\xf1a y contacto exclusivo a trav\\xe9s de support@cojauny.com. Publicaremos los datos registrales en esta p\\xe1gina tan pronto est\\xe9n disponibles.'\n                },\n                {\n                    heading: \"Datos personales que tratamos\",\n                    body: \"Recopilamos la informaci\\xf3n que nos facilitas directamente (nombre, correo profesional, empresa, caso de uso, mensajes) junto a m\\xe9tricas an\\xf3nimas de navegaci\\xf3n como p\\xe1ginas visitadas, idioma, dispositivo o eventos de formularios, adem\\xe1s de registros t\\xe9cnicos necesarios para la seguridad.\"\n                },\n                {\n                    heading: \"Finalidades y bases jur\\xeddicas\",\n                    body: \"Tratamos tus datos para gestionar la solicitud de acceso a la beta y enviarte comunicaciones relacionadas (base jur\\xeddica: tu consentimiento), responder consultas o feedback (inter\\xe9s leg\\xedtimo en mejorar el servicio) y analizar de forma agregada el uso de la web para tomar decisiones de producto (consentimiento para cookies anal\\xedticas y, en lo estrictamente necesario, inter\\xe9s leg\\xedtimo en garantizar la estabilidad y la seguridad).\"\n                },\n                {\n                    heading: \"Destinatarios y transferencias\",\n                    body: \"Solo compartimos datos con proveedores que nos ayudan a prestar el servicio: infraestructura y base de datos (Supabase Europe), alojamiento web (Vercel), correo transaccional (Resend) y anal\\xedtica (Google Analytics 4). Todos operan desde la Uni\\xf3n Europea o aplican Cl\\xe1usulas Contractuales Tipo cuando es necesario transferir datos fuera del EEE. No vendemos ni cedemos tus datos a terceros con fines comerciales.\"\n                },\n                {\n                    heading: \"Plazos de conservaci\\xf3n\",\n                    body: \"Conservamos la informaci\\xf3n durante la fase beta y la eliminamos transcurridos 12 meses desde tu \\xfaltimo contacto o solicitud, salvo obligaci\\xf3n legal distinta o que solicites la supresi\\xf3n antes.\"\n                },\n                {\n                    heading: \"Derechos y reclamaciones\",\n                    body: \"Puedes ejercer los derechos de acceso, rectificaci\\xf3n, oposici\\xf3n, portabilidad, limitaci\\xf3n y supresi\\xf3n escribiendo a support@cojauny.com. Tambi\\xe9n puedes retirar tu consentimiento en cualquier momento. Si consideras que no hemos atendido correctamente tu petici\\xf3n, tienes derecho a reclamar ante la Agencia Espa\\xf1ola de Protecci\\xf3n de Datos (www.aepd.es).\"\n                },\n                {\n                    heading: \"Actualizaciones de esta pol\\xedtica\",\n                    body: \"Revisaremos esta pol\\xedtica cuando cambiemos la forma de tratar tus datos o formalicemos la nueva entidad jur\\xeddica. Avisaremos por los canales disponibles y publicaremos la versi\\xf3n vigente en esta p\\xe1gina.\"\n                }\n            ],\n            contact: \"Para cualquier duda adicional escribe a support@cojauny.com.\"\n        },\n        cookies: {\n            title: \"Pol\\xedtica de cookies\",\n            intro: \"Esta pol\\xedtica detalla c\\xf3mo utilizamos cookies y tecnolog\\xedas similares en la web de Cojauny y complementa nuestra pol\\xedtica de privacidad.\",\n            updatedAt: \"Actualizado el 17 de noviembre de 2025\",\n            sections: [\n                {\n                    heading: \"Qu\\xe9 son las cookies\",\n                    body: \"Las cookies son archivos que el navegador guarda temporalmente para recordar preferencias, garantizar la seguridad o medir la actividad. Tambi\\xe9n utilizamos tecnolog\\xedas similares como localStorage con la misma finalidad.\"\n                },\n                {\n                    heading: \"Cookies que utilizamos\",\n                    body: \"Clasificamos las cookies en: esenciales (sesi\\xf3n, idioma, balanceo de carga), de preferencias (recordar tus elecciones en el banner) y anal\\xedticas (Google Analytics 4 con IP anonimizada). Solo instalamos las categor\\xedas de preferencias y anal\\xedticas cuando otorgas tu consentimiento expl\\xedcito.\"\n                },\n                {\n                    heading: \"C\\xf3mo gestionar el consentimiento\",\n                    body: \"Puedes aceptar o rechazar las cookies opcionales desde el banner inicial o a trav\\xe9s del enlace de configuraci\\xf3n. Tambi\\xe9n puedes borrar o bloquear cookies en tu navegador siguiendo la ayuda de Chrome, Safari, Edge o Firefox.\"\n                },\n                {\n                    heading: \"Transferencias y conservaci\\xf3n\",\n                    body: \"Procesamos los datos generados por las cookies en la Uni\\xf3n Europea siempre que es posible. Cuando colaboramos con proveedores que pueden operar fuera del EEE, aplicamos Cl\\xe1usulas Contractuales Tipo y medidas adicionales de seguridad. Los identificadores anal\\xedticos se conservan durante un m\\xe1ximo de 14 meses.\"\n                },\n                {\n                    heading: \"Actualizaciones\",\n                    body: \"Revisaremos esta pol\\xedtica cuando incorporemos nuevos proveedores o cambiemos los periodos de conservaci\\xf3n. Publicaremos la versi\\xf3n vigente en esta p\\xe1gina.\"\n                }\n            ],\n            contact: \"Si tienes preguntas sobre cookies, cont\\xe1ctanos en support@cojauny.com.\"\n        },\n        terms: {\n            title: \"T\\xe9rminos y condiciones de uso\",\n            intro: \"Estas condiciones regulan el uso del sitio web cojauny.com durante la fase beta. Al navegar por la p\\xe1gina o enviarnos informaci\\xf3n aceptas las cl\\xe1usulas que se describen a continuaci\\xf3n.\",\n            updatedAt: \"Actualizado el 17 de noviembre de 2025\",\n            sections: [\n                {\n                    heading: \"Objeto y alcance\",\n                    body: \"El sitio web ofrece informaci\\xf3n sobre Cojauny y permite solicitar acceso a la beta privada o enviar comentarios sin coste. El servicio es precomercial, puede modificarse en cualquier momento y se presta sin obligaci\\xf3n de disponibilidad continuada.\"\n                },\n                {\n                    heading: \"Requisitos de acceso\",\n                    body: \"Para utilizar los formularios debes ser mayor de 18 a\\xf1os, facilitar datos veraces y contar con autorizaci\\xf3n para compartir informaci\\xf3n de terceras personas. No introduzcas datos confidenciales o sensibles salvo que sean imprescindibles y dispongas de base legal para hacerlo.\"\n                },\n                {\n                    heading: \"Uso aceptable\",\n                    body: \"No est\\xe1 permitido utilizar la web con fines il\\xedcitos, interferir en su funcionamiento, realizar ingenier\\xeda inversa, automatizar descargas masivas ni introducir c\\xf3digo malicioso que pueda afectar a otros usuarios o a nuestra infraestructura.\"\n                },\n                {\n                    heading: \"Propiedad intelectual\",\n                    body: \"El contenido, la marca Cojauny™ y los dise\\xf1os de la web son titularidad del Equipo Cojauny o de sus licenciantes. Se proh\\xedbe copiar, distribuir o crear obras derivadas sin autorizaci\\xf3n expresa, salvo los usos previstos en la ley.\"\n                },\n                {\n                    heading: \"Limitaci\\xf3n de responsabilidad\",\n                    body: \"Prestamos el servicio en estado beta y sin garant\\xedas de disponibilidad, exactitud o adecuaci\\xf3n. No asumimos responsabilidad por da\\xf1os indirectos, p\\xe9rdida de datos o lucro cesante derivados del uso de la web. Tu interacci\\xf3n con proveedores externos corre por tu cuenta.\"\n                },\n                {\n                    heading: \"Modificaciones y contacto\",\n                    body: \"Podemos actualizar estos t\\xe9rminos para reflejar cambios en el servicio o en la legislaci\\xf3n. Publicaremos la versi\\xf3n vigente en esta p\\xe1gina y, si la modificaci\\xf3n es relevante, avisaremos por correo. La relaci\\xf3n se rige por la legislaci\\xf3n espa\\xf1ola y cualquier disputa se somete a los tribunales de Madrid. Puedes escribirnos en cualquier momento a support@cojauny.com.\"\n                }\n            ],\n            contact: \"Para cuestiones legales escribe a support@cojauny.com.\"\n        }\n    },\n    en: {\n        privacy: {\n            title: \"Privacy Policy\",\n            intro: \"We handle personal information responsibly and transparently. This notice describes how we process the data you share when requesting beta access, submitting feedback or browsing the website.\",\n            updatedAt: \"Updated on November 17, 2025\",\n            sections: [\n                {\n                    heading: \"Data controller\",\n                    body: \"Until the company incorporation is completed, data processing is carried out by the Cojauny founding team (the “Cojauny Team”), organised in Spain and reachable exclusively at support@cojauny.com. We will publish the corporate details here as soon as they are available.\"\n                },\n                {\n                    heading: \"Personal data we process\",\n                    body: \"We process the information you provide directly (name, professional email, company, use case, messages), aggregated browsing analytics such as visited pages, language, device or form events, and basic technical logs required for security.\"\n                },\n                {\n                    heading: \"Purposes and legal bases\",\n                    body: \"We use your data to manage beta requests and send related communications (legal basis: your consent), respond to enquiries or feedback (legitimate interest in improving the service) and analyse website usage in aggregate to make product decisions (consent for analytics cookies and, where strictly necessary, legitimate interest in keeping the site stable and secure).\"\n                },\n                {\n                    heading: \"Recipients and transfers\",\n                    body: \"We only share data with providers that help us deliver the service: infrastructure and database (Supabase Europe), hosting (Vercel), transactional email (Resend) and analytics (Google Analytics 4). They operate from the European Union or rely on Standard Contractual Clauses when data leaves the EEA. We never sell or exchange your data for advertising purposes.\"\n                },\n                {\n                    heading: \"Retention period\",\n                    body: \"We keep your information during the beta phase and delete it 12 months after your last interaction or request, unless the law requires a longer period or you request deletion earlier.\"\n                },\n                {\n                    heading: \"Your rights\",\n                    body: \"You can request access, rectification, objection, portability, restriction or erasure by emailing support@cojauny.com. You may withdraw consent at any time. If you believe we have not handled your request properly you can lodge a complaint with the Spanish Data Protection Agency (www.aepd.es).\"\n                },\n                {\n                    heading: \"Policy updates\",\n                    body: \"We will revise this policy whenever we change how we process your data or when the new corporate entity is formalised. We will notify you through the available channels and publish the latest version on this page.\"\n                }\n            ],\n            contact: \"Questions? Reach us at support@cojauny.com.\"\n        },\n        cookies: {\n            title: \"Cookie Policy\",\n            intro: \"This policy explains how Cojauny uses cookies and similar technologies, complementing the information provided in the privacy notice.\",\n            updatedAt: \"Updated on November 17, 2025\",\n            sections: [\n                {\n                    heading: \"What cookies are\",\n                    body: \"Cookies are small files stored by your browser to remember preferences, secure sessions or measure activity. We may also rely on similar technologies such as localStorage for the same purposes.\"\n                },\n                {\n                    heading: \"Cookies we use\",\n                    body: \"We group cookies into essential (session management, language, load balancing), preference (store your choices in the consent banner) and analytics (Google Analytics 4 with IP anonymisation). Preference and analytics cookies only load when you provide explicit consent.\"\n                },\n                {\n                    heading: \"Managing consent\",\n                    body: \"You can accept or reject optional cookies from the initial banner or via the configuration link. You may also delete or block cookies in your browser by following the help pages for Chrome, Safari, Edge or Firefox.\"\n                },\n                {\n                    heading: \"Transfers and retention\",\n                    body: \"We process cookie data within the European Union whenever possible. When providers may operate outside the EEA we rely on Standard Contractual Clauses and additional safeguards. Analytics identifiers are retained for up to 14 months.\"\n                },\n                {\n                    heading: \"Updates\",\n                    body: \"We will update this policy when we add new providers or change retention periods, and the latest version will always be available on this page.\"\n                }\n            ],\n            contact: \"For cookie questions, email support@cojauny.com.\"\n        },\n        terms: {\n            title: \"Terms of Use\",\n            intro: \"These terms govern the use of cojauny.com during the beta phase. By browsing the site or sending us information you agree to the clauses below.\",\n            updatedAt: \"Updated on November 17, 2025\",\n            sections: [\n                {\n                    heading: \"Purpose and scope\",\n                    body: \"The site provides information about Cojauny and lets you request beta access or submit feedback free of charge. The service is pre-commercial, may change at any time and is offered without a commitment of continuous availability.\"\n                },\n                {\n                    heading: \"Eligibility\",\n                    body: \"You must be at least 18 years old, provide accurate information and be authorised to share third-party data. Please avoid submitting confidential or sensitive information unless it is strictly necessary and you have a lawful basis to do so.\"\n                },\n                {\n                    heading: \"Acceptable use\",\n                    body: \"You may not use the site for unlawful purposes, interfere with its operation, reverse engineer its components, automate large-scale extraction or introduce malicious code that could harm other users or our infrastructure.\"\n                },\n                {\n                    heading: \"Intellectual property\",\n                    body: \"The content, design and Cojauny™ brand belong to the Cojauny Team or its licensors. You may not copy, distribute or create derivative works without prior written permission, except where mandatory law allows it.\"\n                },\n                {\n                    heading: \"Liability\",\n                    body: \"The service is provided on a beta and “as is” basis. We do not guarantee accuracy, availability or suitability, and we are not liable for indirect damages, data loss or loss of profit arising from the use of the site. Your interactions with external providers are at your own risk.\"\n                },\n                {\n                    heading: \"Changes and contact\",\n                    body: \"We may update these terms to reflect changes in the service or applicable law. We will publish the current version on this page and notify you by email when the changes are material. Spanish law governs the relationship and any dispute will be submitted to the courts of Madrid. Contact us anytime at support@cojauny.com.\"\n                }\n            ],\n            contact: \"For legal matters contact support@cojauny.com.\"\n        }\n    },\n    de: {\n        privacy: {\n            title: \"Datenschutzerkl\\xe4rung\",\n            intro: \"Wir verarbeiten personenbezogene Daten verantwortungsbewusst und transparent. Diese Erkl\\xe4rung erl\\xe4utert, welche Daten wir erheben, wenn du einen Beta-Zugang anfragst, Feedback sendest oder die Website nutzt.\",\n            updatedAt: \"Aktualisiert am 17. November 2025\",\n            sections: [\n                {\n                    heading: \"Verantwortliche Stelle\",\n                    body: 'Bis zur formellen Gr\\xfcndung der Gesellschaft \\xfcbernimmt das Gr\\xfcnderteam von Cojauny (nachfolgend \"Cojauny-Team\") die Datenverarbeitung. Das Team ist in Spanien organisiert und ausschlie\\xdflich unter support@cojauny.com erreichbar. Die Registerdaten ver\\xf6ffentlichen wir hier, sobald sie vorliegen.'\n                },\n                {\n                    heading: \"Welche Daten wir verarbeiten\",\n                    body: \"Wir verarbeiten die Informationen, die du direkt bereitstellst (Name, berufliche E-Mail, Unternehmen, geplante Nutzung, Nachrichten), aggregierte Nutzungsdaten wie besuchte Seiten, Sprache, Ger\\xe4t oder Formularevents sowie technische Protokolle, die f\\xfcr die Sicherheit erforderlich sind.\"\n                },\n                {\n                    heading: \"Zwecke und Rechtsgrundlagen\",\n                    body: \"Wir nutzen deine Daten, um Beta-Anfragen zu verwalten und dir dazugeh\\xf6rige Informationen zu senden (Rechtsgrundlage: deine Einwilligung), R\\xfcckfragen oder Feedback zu beantworten (berechtigtes Interesse an der Verbesserung des Dienstes) und die Websitenutzung aggregiert auszuwerten (Einwilligung f\\xfcr Analyse-Cookies sowie, soweit unbedingt erforderlich, berechtigtes Interesse an Stabilit\\xe4t und Sicherheit).\"\n                },\n                {\n                    heading: \"Empf\\xe4nger und \\xdcbermittlungen\",\n                    body: \"Wir teilen Daten nur mit Dienstleistern, die uns bei der Bereitstellung unterst\\xfctzen: Infrastruktur und Datenbank (Supabase Europe), Hosting (Vercel), Transaktionsmails (Resend) sowie Analytik (Google Analytics 4). Diese Anbieter agieren innerhalb der EU oder setzen Standardvertragsklauseln ein, wenn Daten den EWR verlassen. Eine Weitergabe zu Werbezwecken findet nicht statt.\"\n                },\n                {\n                    heading: \"Aufbewahrungsdauer\",\n                    body: \"Wir speichern deine Informationen w\\xe4hrend der Beta-Phase und l\\xf6schen sie sp\\xe4testens 12 Monate nach deinem letzten Kontakt oder deiner Anfrage, sofern keine gesetzlichen Pflichten oder deine vorherige L\\xf6schanweisung entgegenstehen.\"\n                },\n                {\n                    heading: \"Deine Rechte\",\n                    body: \"Du kannst Auskunft, Berichtigung, Widerspruch, Daten\\xfcbertragbarkeit, Einschr\\xe4nkung oder L\\xf6schung verlangen, indem du uns an support@cojauny.com schreibst. Eine erteilte Einwilligung kannst du jederzeit widerrufen. Wenn du der Ansicht bist, dass wir dein Anliegen nicht korrekt bearbeitet haben, kannst du Beschwerde bei der spanischen Datenschutzbeh\\xf6rde (www.aepd.es) einlegen.\"\n                },\n                {\n                    heading: \"Aktualisierungen\",\n                    body: \"Wir passen diese Erkl\\xe4rung an, sobald sich unsere Verarbeitung \\xe4ndert oder die neue juristische Person feststeht. \\xdcber relevante \\xc4nderungen informieren wir dich \\xfcber verf\\xfcgbare Kan\\xe4le und ver\\xf6ffentlichen die aktuelle Version auf dieser Seite.\"\n                }\n            ],\n            contact: \"Fragen? Melde dich unter support@cojauny.com.\"\n        },\n        cookies: {\n            title: \"Cookie-Richtlinie\",\n            intro: \"Diese Richtlinie erl\\xe4utert, wie Cojauny Cookies und \\xe4hnliche Technologien einsetzt und erg\\xe4nzt die Hinweise in der Datenschutzerkl\\xe4rung.\",\n            updatedAt: \"Aktualisiert am 17. November 2025\",\n            sections: [\n                {\n                    heading: \"Was sind Cookies\",\n                    body: \"Cookies sind kleine Dateien, die der Browser speichert, um Einstellungen zu merken, Sitzungen zu sichern oder Aktivit\\xe4ten zu messen. Wir nutzen bei Bedarf vergleichbare Technologien wie localStorage mit denselben Zielen.\"\n                },\n                {\n                    heading: \"Welche Cookies wir einsetzen\",\n                    body: \"Wir unterscheiden zwischen essenziellen Cookies (Sitzungsverwaltung, Sprache, Lastverteilung), Pr\\xe4ferenz-Cookies (speichern deine Auswahl im Consent-Banner) und Analyse-Cookies (Google Analytics 4 mit anonymisierter IP). Pr\\xe4ferenz- und Analyse-Cookies setzen wir ausschlie\\xdflich nach deiner ausdr\\xfccklichen Einwilligung.\"\n                },\n                {\n                    heading: \"Einwilligung verwalten\",\n                    body: \"Du kannst optionale Cookies \\xfcber das Banner annehmen oder ablehnen und deine Entscheidung jederzeit \\xfcber den Einstellungslink \\xe4ndern. Zus\\xe4tzlich lassen sich Cookies in deinem Browser (Chrome, Safari, Edge, Firefox) l\\xf6schen oder blockieren.\"\n                },\n                {\n                    heading: \"\\xdcbermittlungen und Speicherfrist\",\n                    body: \"Wir verarbeiten Cookie-Daten nach M\\xf6glichkeit innerhalb der EU. Falls Dienstleister au\\xdferhalb des EWR agieren, nutzen wir Standardvertragsklauseln und zus\\xe4tzliche Schutzma\\xdfnahmen. Analyse-IDs bewahren wir h\\xf6chstens 14 Monate auf.\"\n                },\n                {\n                    heading: \"\\xc4nderungen\",\n                    body: \"Wir aktualisieren diese Richtlinie, wenn neue Anbieter hinzukommen oder sich Speicherfristen \\xe4ndern. Die jeweils g\\xfcltige Version findest du stets auf dieser Seite.\"\n                }\n            ],\n            contact: \"Bei Fragen zu Cookies erreichst du uns unter support@cojauny.com.\"\n        },\n        terms: {\n            title: \"Nutzungsbedingungen\",\n            intro: \"Diese Bedingungen regeln die Nutzung von cojauny.com w\\xe4hrend der Beta-Phase. Wenn du die Website verwendest oder uns Informationen sendest, akzeptierst du die folgenden Regelungen.\",\n            updatedAt: \"Aktualisiert am 17. November 2025\",\n            sections: [\n                {\n                    heading: \"Zweck und Geltungsbereich\",\n                    body: \"Die Website stellt Informationen \\xfcber Cojauny bereit und erm\\xf6glicht kostenlose Beta-Anfragen sowie Feedback. Der Dienst ist vorkommerziell, kann jederzeit ver\\xe4ndert werden und wird ohne Garantie auf dauerhafte Verf\\xfcgbarkeit bereitgestellt.\"\n                },\n                {\n                    heading: \"Zugangsvoraussetzungen\",\n                    body: \"Du musst mindestens 18 Jahre alt sein, korrekte Angaben machen und berechtigt sein, Daten Dritter zu teilen. Verzichte darauf, vertrauliche oder sensible Informationen zu \\xfcbermitteln, sofern dies nicht unbedingt erforderlich und rechtlich zul\\xe4ssig ist.\"\n                },\n                {\n                    heading: \"Akzeptable Nutzung\",\n                    body: \"Es ist untersagt, die Website zu illegalen Zwecken zu verwenden, ihren Betrieb zu st\\xf6ren, Komponenten zur\\xfcckzuentwickeln, automatisierte Massendownloads durchzuf\\xfchren oder sch\\xe4dlichen Code einzuschleusen, der andere Nutzer oder unsere Infrastruktur beeintr\\xe4chtigen k\\xf6nnte.\"\n                },\n                {\n                    heading: \"Geistiges Eigentum\",\n                    body: \"Inhalte, Gestaltung und die Marke Cojauny™ geh\\xf6ren dem Cojauny-Team oder seinen Lizenzgebern. Kopieren, Verteilen oder Ableiten ist ohne vorherige schriftliche Zustimmung unzul\\xe4ssig, soweit das Gesetz nichts anderes vorsieht.\"\n                },\n                {\n                    heading: \"Haftung\",\n                    body: \"Der Dienst befindet sich in der Beta-Phase und wird ohne Gew\\xe4hr bereitgestellt. Wir \\xfcbernehmen keine Haftung f\\xfcr mittelbare Sch\\xe4den, Datenverluste oder entgangenen Gewinn, die durch die Nutzung der Website entstehen. Interaktionen mit externen Anbietern erfolgen auf eigene Verantwortung.\"\n                },\n                {\n                    heading: \"\\xc4nderungen und Kontakt\",\n                    body: \"Wir k\\xf6nnen diese Bedingungen anpassen, wenn sich der Dienst oder die Rechtslage \\xe4ndert. Die aktuelle Fassung ver\\xf6ffentlichen wir auf dieser Seite und informieren bei wesentlichen \\xc4nderungen per E-Mail. Es gilt spanisches Recht; Gerichtsstand ist Madrid. F\\xfcr R\\xfcckfragen kannst du uns jederzeit unter support@cojauny.com schreiben.\"\n                }\n            ],\n            contact: \"Rechtliche Anfragen an support@cojauny.com.\"\n        }\n    },\n    fr: {\n        privacy: {\n            title: \"Politique de confidentialit\\xe9\",\n            intro: \"Nous traitons vos donn\\xe9es personnelles avec responsabilit\\xe9 et transparence. Cette politique d\\xe9taille les informations que nous collectons lorsque vous demandez l’acc\\xe8s \\xe0 la b\\xeata, partagez un retour ou naviguez sur le site.\",\n            updatedAt: \"Mis \\xe0 jour le 17 novembre 2025\",\n            sections: [\n                {\n                    heading: \"Responsable du traitement\",\n                    body: \"Le traitement est assur\\xe9 par l’\\xe9quipe fondatrice de Cojauny (ci-apr\\xe8s \\xab \\xc9quipe Cojauny \\xbb) tant que l’entit\\xe9 juridique d\\xe9finitive n’est pas constitu\\xe9e. L’\\xe9quipe est organis\\xe9e en Espagne et joignable exclusivement \\xe0 support@cojauny.com. Les informations d’immatriculation seront publi\\xe9es sur cette page d\\xe8s qu’elles seront disponibles.\"\n                },\n                {\n                    heading: \"Donn\\xe9es que nous traitons\",\n                    body: \"Nous collectons les informations fournies directement (nom, e-mail professionnel, entreprise, cas d’usage, messages), des m\\xe9triques de navigation agr\\xe9g\\xe9es telles que pages consult\\xe9es, langue, appareil ou \\xe9v\\xe9nements de formulaires, ainsi que des journaux techniques n\\xe9cessaires \\xe0 la s\\xe9curit\\xe9.\"\n                },\n                {\n                    heading: \"Finalit\\xe9s et bases l\\xe9gales\",\n                    body: \"Nous utilisons vos donn\\xe9es pour g\\xe9rer les demandes d’acc\\xe8s \\xe0 la b\\xeata et vous adresser des communications associ\\xe9es (base l\\xe9gale : votre consentement), r\\xe9pondre aux questions ou retours (int\\xe9r\\xeat l\\xe9gitime \\xe0 am\\xe9liorer le service) et analyser de mani\\xe8re agr\\xe9g\\xe9e l’usage du site (consentement pour les cookies analytiques et, si n\\xe9cessaire, int\\xe9r\\xeat l\\xe9gitime \\xe0 garantir la stabilit\\xe9 et la s\\xe9curit\\xe9).\"\n                },\n                {\n                    heading: \"Destinataires et transferts\",\n                    body: \"Nous partageons les donn\\xe9es uniquement avec les prestataires qui nous aident \\xe0 fournir le service : infrastructure et base de donn\\xe9es (Supabase Europe), h\\xe9bergement (Vercel), e-mails transactionnels (Resend) et analytique (Google Analytics 4). Ces prestataires op\\xe8rent dans l’Union europ\\xe9enne ou appliquent des Clauses Contractuelles Types lorsqu’une exportation hors EEE est n\\xe9cessaire. Nous ne vendons ni n’\\xe9changeons vos donn\\xe9es \\xe0 des fins publicitaires.\"\n                },\n                {\n                    heading: \"Dur\\xe9es de conservation\",\n                    body: \"Les informations sont conserv\\xe9es pendant la phase b\\xeata puis supprim\\xe9es 12 mois apr\\xe8s votre dernier contact ou demande, sauf obligation l\\xe9gale contraire ou suppression anticip\\xe9e \\xe0 votre demande.\"\n                },\n                {\n                    heading: \"Vos droits\",\n                    body: \"Vous pouvez demander l’acc\\xe8s, la rectification, l’opposition, la portabilit\\xe9, la limitation ou l’effacement en \\xe9crivant \\xe0 support@cojauny.com. Vous pouvez retirer votre consentement \\xe0 tout moment. Si vous estimez que votre demande n’a pas \\xe9t\\xe9 trait\\xe9e correctement, vous pouvez saisir l’Agence espagnole de protection des donn\\xe9es (www.aepd.es).\"\n                },\n                {\n                    heading: \"Mises \\xe0 jour\",\n                    body: \"Nous r\\xe9viserons cette politique si nos traitements \\xe9voluent ou lorsque l’entit\\xe9 juridique sera formalis\\xe9e. Nous vous informerons par les canaux disponibles et publierons la version la plus r\\xe9cente sur cette page.\"\n                }\n            ],\n            contact: \"Pour toute question, \\xe9crivez \\xe0 support@cojauny.com.\"\n        },\n        cookies: {\n            title: \"Politique de cookies\",\n            intro: \"La pr\\xe9sente politique d\\xe9crit l’usage des cookies et technologies similaires sur cojauny.com et compl\\xe8te les informations fournies dans la politique de confidentialit\\xe9.\",\n            updatedAt: \"Mis \\xe0 jour le 17 novembre 2025\",\n            sections: [\n                {\n                    heading: \"Ce que sont les cookies\",\n                    body: \"Les cookies sont de petits fichiers enregistr\\xe9s par votre navigateur pour m\\xe9moriser des pr\\xe9f\\xe9rences, s\\xe9curiser les sessions ou mesurer l’activit\\xe9. Nous pouvons \\xe9galement utiliser des technologies \\xe9quivalentes comme le localStorage aux m\\xeames fins.\"\n                },\n                {\n                    heading: \"Cookies que nous utilisons\",\n                    body: \"Nous distinguons les cookies essentiels (gestion de session, langue, r\\xe9partition de charge), de pr\\xe9f\\xe9rence (m\\xe9morisent vos choix dans la banni\\xe8re de consentement) et analytiques (Google Analytics 4 avec anonymisation d’IP). Les cookies de pr\\xe9f\\xe9rence et analytiques ne sont d\\xe9pos\\xe9s qu’avec votre consentement explicite.\"\n                },\n                {\n                    heading: \"Gestion du consentement\",\n                    body: \"Vous pouvez accepter ou refuser les cookies optionnels depuis la banni\\xe8re initiale ou via le lien de configuration. Il est \\xe9galement possible de supprimer ou bloquer les cookies dans votre navigateur (Chrome, Safari, Edge, Firefox).\"\n                },\n                {\n                    heading: \"Transferts et dur\\xe9e de conservation\",\n                    body: \"Nous traitons les donn\\xe9es issues des cookies au sein de l’Union europ\\xe9enne autant que possible. Lorsque des prestataires op\\xe8rent en dehors de l’EEE, nous appliquons des Clauses Contractuelles Types et des mesures de s\\xe9curit\\xe9 suppl\\xe9mentaires. Les identifiants analytiques sont conserv\\xe9s au maximum 14 mois.\"\n                },\n                {\n                    heading: \"\\xc9volutions\",\n                    body: \"Nous mettrons cette politique \\xe0 jour en cas de nouveaux prestataires ou de changement de dur\\xe9e de conservation. La version la plus r\\xe9cente restera disponible sur cette page.\"\n                }\n            ],\n            contact: \"Questions sur les cookies ? support@cojauny.com.\"\n        },\n        terms: {\n            title: \"Conditions d’utilisation\",\n            intro: \"Les pr\\xe9sentes conditions r\\xe9gissent l’usage de cojauny.com pendant la phase b\\xeata. En consultant le site ou en nous adressant des informations, vous acceptez les clauses suivantes.\",\n            updatedAt: \"Mis \\xe0 jour le 17 novembre 2025\",\n            sections: [\n                {\n                    heading: \"Objet et port\\xe9e\",\n                    body: \"Le site fournit des informations sur Cojauny et permet de demander un acc\\xe8s \\xe0 la b\\xeata ou d’envoyer un retour sans frais. Le service est pr\\xe9commercial, susceptible d’\\xe9voluer \\xe0 tout moment et fourni sans garantie de disponibilit\\xe9 continue.\"\n                },\n                {\n                    heading: \"Conditions d’acc\\xe8s\",\n                    body: \"Vous devez avoir au moins 18 ans, fournir des informations exactes et \\xeatre autoris\\xe9 \\xe0 partager des donn\\xe9es de tiers. Veuillez \\xe9viter de transmettre des donn\\xe9es confidentielles ou sensibles sauf n\\xe9cessit\\xe9 absolue et base l\\xe9gale ad\\xe9quate.\"\n                },\n                {\n                    heading: \"Utilisation acceptable\",\n                    body: \"Il est interdit d’utiliser le site \\xe0 des fins illicites, d’en perturber le fonctionnement, d’effectuer de l’ing\\xe9nierie inverse, d’automatiser des extractions massives ou d’introduire du code malveillant pouvant nuire \\xe0 d’autres utilisateurs ou \\xe0 notre infrastructure.\"\n                },\n                {\n                    heading: \"Propri\\xe9t\\xe9 intellectuelle\",\n                    body: \"Le contenu, le design et la marque Cojauny™ sont la propri\\xe9t\\xe9 de l’\\xc9quipe Cojauny ou de ses conc\\xe9dants. Toute reproduction, distribution ou cr\\xe9ation d’œuvres d\\xe9riv\\xe9es est interdite sans autorisation \\xe9crite pr\\xe9alable, sauf dispositions l\\xe9gales contraires.\"\n                },\n                {\n                    heading: \"Responsabilit\\xe9\",\n                    body: \"Le service est fourni en version b\\xeata et \\xab en l’\\xe9tat \\xbb. Nous n’offrons aucune garantie d’exactitude, de disponibilit\\xe9 ou d’ad\\xe9quation et d\\xe9clinons toute responsabilit\\xe9 pour les dommages indirects, la perte de donn\\xe9es ou le manque \\xe0 gagner li\\xe9s \\xe0 l’usage du site. Les interactions avec des prestataires externes rel\\xe8vent de votre responsabilit\\xe9.\"\n                },\n                {\n                    heading: \"Modifications et contact\",\n                    body: \"Nous pouvons modifier ces conditions pour refl\\xe9ter l’\\xe9volution du service ou de la l\\xe9gislation. La version en vigueur sera publi\\xe9e sur cette page et nous vous pr\\xe9viendrons par e-mail en cas de changement substantiel. Le droit espagnol s’applique et tout litige sera port\\xe9 devant les tribunaux de Madrid. Vous pouvez nous contacter \\xe0 support@cojauny.com.\"\n                }\n            ],\n            contact: \"Pour toute demande l\\xe9gale, \\xe9crivez \\xe0 support@cojauny.com.\"\n        }\n    }\n};\nconst getLegalCopy = (locale)=>legalCopy[locale] ?? legalCopy[_config__WEBPACK_IMPORTED_MODULE_0__.defaultLocale];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/locales/legal.ts\n");

